sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	gs.info('BUSINESS RULE FIRED for ' + current.number);

    var deptCategory = current.department.getDisplayValue(); // "Engineering" / "Housekeeping" — matches SLA Def's Category
    var urgencyPriority = current.priority;    // "high"/"medium"/"low" — matches SLA Def's Priority
    var propertySysId = current.department.property;

	gs.info('DEBUG values -> category=' + deptCategory + ' priority=' + urgencyPriority + ' property=' + propertySysId);

    if (!deptCategory || !urgencyPriority || !propertySysId) {
        gs.warn('Guest Case ' + current.number + ': missing Category, Priority, or Property — cannot calculate SLA due date.');
        return;
    }

    var slaGr = new GlideRecord('x_snc_flowops_sla_defination');
    slaGr.addQuery('category', deptCategory);
    slaGr.addQuery('priority', urgencyPriority);
    slaGr.addQuery('property', propertySysId);
    slaGr.query();

    if (slaGr.next()) {
        var resolutionMins = slaGr.getValue('resolution_time_mins');

        var dueDate = new GlideDateTime();
        dueDate.addSeconds(resolutionMins * 60);

        current.sla_due_time = dueDate;

    } else {
        gs.warn('Guest Case ' + current.number + ': no matching SLA Definition found for Category=' + deptCategory + ', Priority=' + urgencyPriority + ', Property=' + propertySysId);
    }

})(current, previous);
